                                        val newWidthPx = with(density) { sidebarWidth.toPx() } + dragAmount.x
                                        val newWidth = with(density) { newWidthPx.toDp() }
                                        sidebarWidth = newWidth.coerceIn(minSidebarWidth, maxSidebarWidth)
                                    }
