                Row(modifier = Modifier.fillMaxHeight()) {
                    Surface(
                        modifier = Modifier
                            .fillMaxHeight()
                            .width(if (isSidebarOpen) sidebarWidth else collapsedSidebarWidth),
                        color = MaterialTheme.colorScheme.surfaceVariant,
                        tonalElevation = 2.dp
                    ) {
                        if (isSidebarOpen) {
                            // Expanded sidebar with full content
                            Column(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                // Header with hamburger button
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    IconButton(onClick = { isSidebarOpen = false }) {
                                        SunriseLogo(size = 32)
                                    }
                                    Text(
                                        "日出",
                                        style = MaterialTheme.typography.headlineSmall,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                                HorizontalDivider()
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Text("🏠", style = MaterialTheme.typography.titleLarge)
                                    Text("Menu Item 1")
                                }
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Text("⚙️", style = MaterialTheme.typography.titleLarge)
                                    Text("Menu Item 2")
                                }
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Text("📊", style = MaterialTheme.typography.titleLarge)
                                    Text("Menu Item 3")
                                }
                            }
                        } else {
                            // Collapsed sidebar with icons only
                            Column(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(vertical = 16.dp),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                // Hamburger button
                                IconButton(onClick = { isSidebarOpen = true }) {
                                    SunriseLogo(size = 32)
                                }
                                HorizontalDivider(modifier = Modifier.padding(horizontal = 8.dp))
                                // Icon-only menu items
                                IconButton(onClick = { /* Menu Item 1 action */ }) {
                                    Text("🏠", style = MaterialTheme.typography.titleLarge)
                                }
                                IconButton(onClick = { /* Menu Item 2 action */ }) {
                                    Text("⚙️", style = MaterialTheme.typography.titleLarge)
                                }
                                IconButton(onClick = { /* Menu Item 3 action */ }) {
                                    Text("📊", style = MaterialTheme.typography.titleLarge)
                                }
                            }
                        }
                    }

                    // Resizable divider - only show when sidebar is open
                    if (isSidebarOpen) {
                        Box(
                            modifier = Modifier
                                .fillMaxHeight()
                                .width(4.dp)
                                .background(MaterialTheme.colorScheme.outlineVariant)
                                .pointerHoverIcon(PointerIcon.Hand)
                                .pointerInput(Unit) {
                                    detectDragGestures { change, dragAmount ->
                                        change.consume()
                                        val newWidthPx = with(density) { sidebarWidth.toPx() } + dragAmount.x
                                        val newWidth = with(density) { newWidthPx.toDp() }
                                        sidebarWidth = newWidth.coerceIn(minSidebarWidth, maxSidebarWidth)
                                    }
                                }
                        )
                    }
                }

                // Main Content Area
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(MaterialTheme.colorScheme.background)
                        .padding(16.dp)
                ) {
                    // Top bar header
                    Text(
                        "Main Content",
                        style = MaterialTheme.typography.headlineMedium,
                        modifier = Modifier.fillMaxWidth()
                    )

                    Spacer(modifier = Modifier.height(16.dp))

                    // Original content
                    var showContent by remember { mutableStateOf(false) }
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Button(onClick = { showContent = !showContent }, shape = MaterialTheme.shapes.medium) {
                            Text("Click THIS!")
                        }
                        AnimatedVisibility(showContent) {
                            val greeting = remember { Greeting().greet() }
                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalAlignment = Alignment.CenterHorizontally,
                            ) {
                                Image(painterResource(Res.drawable.compose_multiplatform), null)
                                Text("Compose: $greeting")
                            }
                        }
                    }
                }
            }
        }
    }
}

