        @SerialName("event_id") override val eventId: String,
        @SerialName("room_id") override val roomId: String,
        override val sender: String,
        @SerialName("origin_server_ts") override val timestamp: Long,
        val membership: String,
        @SerialName("state_key") val stateKey: String
    ) : MatrixEvent()

    @Serializable
    @SerialName("m.room.create")
    data class RoomCreateEvent(
        @SerialName("event_id") override val eventId: String,
        @SerialName("room_id") override val roomId: String,
        override val sender: String,
        @SerialName("origin_server_ts") override val timestamp: Long,
        val creator: String
    ) : MatrixEvent()
}

/**
 * Message event content from Matrix protocol
 */
@Serializable
data class MessageEventContent(
    val msgtype: String,
    val body: String,
    val format: String? = null,
    @SerialName("formatted_body") val formattedBody: String? = null,
    val url: String? = null
)

/**
 * Login request
 */
@Serializable
data class LoginRequest(
    val type: String = "m.login.password",
    val identifier: Identifier,
    val password: String
)

@Serializable
data class Identifier(
    val type: String = "m.id.user",
