import com.lostinspacebar.hinode.matrix.MatrixClient

/**
 * Platform-specific factory for creating app dependencies
 */
expect class AppDependencies {
    fun createDatabaseDriverFactory(): DatabaseDriverFactory
    fun createCredentialStorage(): CredentialStorage
}

/**
 * Create MatrixRepository with platform-specific dependencies
 */
fun createMatrixRepository(dependencies: AppDependencies, serverUrl: String = "https://matrix.org"): MatrixRepository {
    val driverFactory = dependencies.createDatabaseDriverFactory()
    val database = createDatabase(driverFactory)
    val credentialStorage = dependencies.createCredentialStorage()
    val matrixClient = MatrixClient(serverUrl)

    return MatrixRepository(database, matrixClient, credentialStorage)
}

