package com.lostinspacebar.hinode.matrix

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Matrix User representation
 */
@Serializable
data class User(
    @SerialName("user_id") val userId: String,
    val displayName: String? = null,
    val avatarUrl: String? = null,
    val presence: Presence = Presence.OFFLINE
)

/**
 * User presence state
 */
@Serializable
enum class Presence {
    @SerialName("online") ONLINE,
    @SerialName("offline") OFFLINE,
    @SerialName("unavailable") UNAVAILABLE
}

/**
 * Matrix Room representation
 */
@Serializable
data class Room(
    val id: String,
    val name: String,
    val topic: String? = null,
    val avatarUrl: String? = null,
    val members: List<User> = emptyList(),
    val isDirect: Boolean = false,
    val isEncrypted: Boolean = false
)

/**
 * Matrix Message representation
 */
@Serializable
data class Message(
    val id: String,
    val roomId: String,
    val sender: User,
    val content: MessageContent,
    val timestamp: Long,
    val deliveryStatus: DeliveryStatus = DeliveryStatus.SENT
)

/**
 * Message delivery status
 */
@Serializable
enum class DeliveryStatus {
    @SerialName("pending") PENDING,
    @SerialName("sent") SENT,
    @SerialName("delivered") DELIVERED,
    @SerialName("failed") FAILED
}

/**
 * Message content types
 */
@Serializable
sealed class MessageContent {
    @Serializable
    @SerialName("text")
    data class Text(val body: String, val formatted: String? = null) : MessageContent()

    @Serializable
