     */
    suspend fun createRoom(
        name: String,
        topic: String? = null,
        isDirect: Boolean = false,
        inviteUsers: List<String> = emptyList()
    ): Result<String> {
        return try {
            // TODO: Implement with Trixnity
            Result.failure(Exception("Not implemented yet"))
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

