                client.close()
            }
            matrixClient = null
            credentialStorage.clearCredentials()
            _currentUser.value = null
            _rooms.value = emptyList()
            _messages.value = emptyMap()
            _connectionStatus.value = ConnectionStatus.DISCONNECTED
            Result.success(Unit)
