/**
 * Android singleton to hold application context
 */
object AndroidContext {
    lateinit var appContext: Context
        private set

    fun init(context: Context) {
        appContext = context.applicationContext
    }
}

/**
 * Android implementation - creates MatrixRepository with Android-specific dependencies
 */
actual fun createMatrixRepository(serverUrl: String): MatrixRepository {
    val context = AndroidContext.appContext
    val driverFactory = DatabaseDriverFactory(context)
    val database = createDatabase(driverFactory)
    val credentialStorage = CredentialStorage(context)
    val matrixClient = MatrixClient(serverUrl)

    return MatrixRepository(database, matrixClient, credentialStorage)
}

